declare function require(id: string): any;
const crypto = require("crypto");

function hashInt(s: string): number {
  return parseInt(crypto.createHash("md5").update(s).digest("hex").slice(0, 8), 16);
}

export class HashRing {
  private ring = new Map<number, string>();
  private sortedPoints: number[] = [];

  constructor(nodes: string[], private replicas: number) {
    for (const node of nodes) {
      this.addNode(node);
    }
  }

  addNode(node: string): void {
    for (let i = 0; i < this.replicas; i++) {
      this.ring.set(hashInt(`${node}:${i}`), node);
    }
    this.sortedPoints = [...this.ring.keys()].sort((a, b) => a - b);
  }

  removeNode(node: string): void {
    for (let i = 0; i < this.replicas; i++) {
      this.ring.delete(hashInt(`${node}:${i}`));
    }
    this.sortedPoints = [...this.ring.keys()].sort((a, b) => a - b);
  }

  getNode(key: string): string {
    if (this.ring.size === 0) {
      throw new Error("no nodes");
    }
    const point = hashInt(key);
    for (const p of this.sortedPoints) {
      if (p >= point) {
        return this.ring.get(p) as string;
      }
    }
    return this.ring.get(this.sortedPoints[0]) as string;
  }
}

