const assert = require("assert");
const { HashRing } = require("./build/ring.js");

{
  const ring = new HashRing(["a", "b", "c"], 50);
  for (let i = 0; i < 200; i++) {
    const node = ring.getNode(`key-${i}`);
    assert.ok(["a", "b", "c"].includes(node));
  }
}
{
  const ring = new HashRing(["a", "b", "c"], 50);
  assert.strictEqual(ring.getNode("stable-key"), ring.getNode("stable-key"));
}
{
  const nodes = ["n0", "n1", "n2", "n3", "n4"];
  const ring = new HashRing(nodes, 100);
  const keys = Array.from({ length: 1000 }, (_, i) => `key-${i}`);
  const before = new Map(keys.map((k) => [k, ring.getNode(k)]));
  ring.removeNode("n2");
  const after = new Map(keys.map((k) => [k, ring.getNode(k)]));
  const moved = keys.filter((k) => before.get(k) !== after.get(k));
  assert.ok(moved.length > 0, "removing a node should move at least some keys");
  for (const k of moved) {
    assert.strictEqual(before.get(k), "n2", "only keys that were on the removed node may move");
  }
  for (const k of keys) {
    assert.notStrictEqual(after.get(k), "n2");
  }
}
console.log("behavior OK");
